export function getPost(slug) {
  return posts.find((p) => p.slug === slug);
}

// Related posts by shared tags (for internal linking / topic clusters).
// Ranks other posts by number of overlapping tags, then recency; returns top `limit`.
export function getRelatedPosts(slug, limit = 3) {
  const current = getPost(slug);
  if (!current) return [];
  const tags = new Set(current.tags || []);
  return posts
    .filter((p) => p.slug !== slug)
    .map((p) => ({ p, overlap: (p.tags || []).filter((t) => tags.has(t)).length }))
    .filter((x) => x.overlap > 0)
    .sort((a, b) => b.overlap - a.overlap || (a.p.date < b.p.date ? 1 : -1))
    .slice(0, limit)
    .map((x) => x.p);
}


export function slugifyTag(tag) {
  return tag.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
}

// All distinct tags with slugs, sorted by post count desc.
export function getAllTags() {
  const counts = new Map();
  for (const p of posts) for (const t of p.tags || []) counts.set(t, (counts.get(t) || 0) + 1);
  return [...counts.entries()]
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .map(([tag, count]) => ({ tag, slug: slugifyTag(tag), count }));
}

export function getPostsByTagSlug(slug) {
  return posts.filter((p) => (p.tags || []).some((t) => slugifyTag(t) === slug));
}
